import React, { useEffect, useRef, useState } from "react";
import FoodOrderPaymentsTable from "./FoodOrderPaymentsTable";

import useApi from "../../../hooks/useApi";
import { useNavigate } from "react-router-dom";
import FoodFormModal from "./FoodFormModal";
import { ToastContainer, toast } from "react-toastify";
import restaurantApi from "../../../api/restaurants/restaurantApi";
import { usePageVisibility } from "../../../hooks/userPageVisibility";

const columns = [
  { name: "Reference", uid: "reference_number" },
  { name: "Amount (KES)", uid: "amount" },
  { name: "Payment Method", uid: "payment_method_title" },
  { name: "Status", uid: "status" },
  { name: "PSP Ref", uid: "psp_reference_number" },
  { name: "Provider Ref", uid: "provider_reference_number" },
  { name: "Description", uid: "description" },
  { name: "Created At", uid: "created" },
  { name: "MMO", uid: "telco" },
  { name: "Is Settled", uid: "is_settled" },
  { name: "Actions", uid: "actions" },
];

function FoodOrderPaymentsList() {
  const [openEditModal, setopenEditModal] = useState(false);

  const navigate = useNavigate();
  const [menu, setMenu] = useState();
  const [foodOrderPayments, setfoodOrderPayments] = useState([]);
  const [data, setdata] = useState([]);
  const [updated, setUpdated] = useState(false);
  const [modalTitle, setmodalTitle] = useState("");
  const restaurantActionsApi = useApi(restaurantApi.restaurantAction);
  const [selectedDates, setSelectedDates] = useState();

  const getBranchFoodOrderPayments = async () => {
    await restaurantActionsApi.request({
      action: "GetFoodOrdersPayments",
    });
  };
  useEffect(() => {
    setdata(foodOrderPayments);
  }, [foodOrderPayments]);

  const handleFilter = (e) => {
    console.log("eeeee", e);
    const search_param = e;

    if (
      foodOrderPayments &&
      foodOrderPayments.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        foodOrderPayments.filter((x) =>
          x.title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(foodOrderPayments);
    }
  };

  useEffect(() => {
    getBranchFoodOrderPayments();
  }, []);

  const isPageVisible = usePageVisibility();
  const timerIdRef = useRef(null);
  const [isPollingEnabled, setIsPollingEnabled] = useState(true);

  useEffect(() => {
    const pollingCallback = () => {
      // Your polling logic here
      console.log("Polling...");
      getBranchFoodOrderPayments();

      // Simulating an API failure in the polling callback
      //   const shouldFail = Math.random() < 0.2; // Simulate 20% chance of API failure

      //   if (shouldFail) {
      //     setIsPollingEnabled(false);
      //     console.log("Polling failed. Stopped polling.");
      //   }
    };

    const startPolling = () => {
      // pollingCallback(); // To immediately start fetching data
      // Polling every 10 seconds
      timerIdRef.current = setInterval(pollingCallback, 5000);
    };

    const stopPolling = () => {
      clearInterval(timerIdRef.current);
    };

    if (isPageVisible && isPollingEnabled) {
      startPolling();
    } else {
      stopPolling();
    }

    return () => {
      stopPolling();
    };
  }, [isPageVisible, isPollingEnabled, getBranchFoodOrderPayments]);

  const getFoodOrderPaymentsByDate = async () => {
    await restaurantActionsApi.request({
      action: "GetFoodOrdersPayments",
      from_date: selectedDates ? selectedDates[0] : "",
      to_date: selectedDates ? selectedDates[1] : "",
    });
  };

  useEffect(() => {
    if (selectedDates) {
      getFoodOrderPaymentsByDate();
    }
  }, [selectedDates]);

  const handleEditAction = (item) => {
    setopenEditModal(true);
    setMenu(item);
    setmodalTitle(`EDIT ${item.title}`);
    setUpdated(false);
  };

  const handleAddAction = () => {
    setopenEditModal(true);
    setmodalTitle("Add new food Item");
    setMenu(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/routes/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/routes/delete/${item.id}`);
  };

  useEffect(() => {
    if (restaurantActionsApi.data && restaurantActionsApi.data.length) {
      setfoodOrderPayments(restaurantActionsApi.data);
    }

    if (
      restaurantActionsApi.data &&
      restaurantActionsApi.data.response_message &&
      restaurantActionsApi.data.response_code === 1
    ) {
      toast.error(restaurantActionsApi.data.response_message);
    }

    if (
      restaurantActionsApi.data &&
      restaurantActionsApi.data.response_message &&
      restaurantActionsApi.data.response_code === 0
    ) {
      toast.success(restaurantActionsApi.data.response_message);
    }

    console.log("transportActionsApi.data", restaurantActionsApi.data);
  }, [restaurantActionsApi.data]);

  useEffect(() => {
    getBranchFoodOrderPayments();
  }, [updated]);

  return (
    <div>
      <ToastContainer position="bottom-center" theme="colored" />
      {openEditModal && (
        <FoodFormModal
          openEditModal={openEditModal}
          setopenEditModal={setopenEditModal}
          item={menu}
          updated={updated}
          setUpdated={setUpdated}
          modalTitle={modalTitle}
        />
      )}
      <FoodOrderPaymentsTable
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
        selectedDates={selectedDates}
        setSelectedDates={setSelectedDates}
      />
    </div>
  );
}

export default FoodOrderPaymentsList;
